using System.Net;
using System.Text;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.IntegrationTest.PaymentGateway;

/// <summary>
/// Exercises HttpPaymentGateway against a real HTTP server so the wire contract with the
/// payment provider is verified end to end: the request we send, and every shape of answer
/// we must read back correctly, including an outright refusal.
/// </summary>
public sealed class HttpPaymentGatewayTests : IAsyncLifetime
{
    private readonly FakeProviderServer server = new();
    private Infrastructure.HttpPaymentGateway sut = null!;

    public Task InitializeAsync()
    {
        server.Start();
        sut = new Infrastructure.HttpPaymentGateway(new HttpClient { BaseAddress = new Uri(server.BaseAddress) });
        return Task.CompletedTask;
    }

    public Task DisposeAsync()
    {
        server.Dispose();
        return Task.CompletedTask;
    }

    [Fact]
    public async Task Sends_reference_amount_and_currency_as_the_provider_expects()
    {
        server.RespondWith(HttpStatusCode.OK, """{"status":"approved"}""");

        await sut.AuthorizeAsync("ORD-1", new Money(42.50m, "eur"), CancellationToken.None);

        var request = server.LastRequest;
        Assert.Equal("POST", request.Method);
        Assert.Equal("/v1/authorizations", request.Path);
        Assert.Equal("""{"reference":"ORD-1","amount":42.50,"currency":"EUR"}""", request.Body);
    }

    [Fact]
    public async Task An_approved_response_is_read_back_as_approved()
    {
        server.RespondWith(HttpStatusCode.OK, """{"status":"approved"}""");

        var outcome = await sut.AuthorizeAsync("ORD-2", new Money(10m, "EUR"), CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Approved, outcome);
    }

    [Fact]
    public async Task A_declined_response_is_read_back_as_declined()
    {
        server.RespondWith(HttpStatusCode.OK, """{"status":"declined"}""");

        var outcome = await sut.AuthorizeAsync("ORD-3", new Money(10m, "EUR"), CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Fact]
    public async Task The_provider_refusing_the_payment_outright_is_read_back_as_declined()
    {
        server.RespondWith(HttpStatusCode.PaymentRequired, "");

        var outcome = await sut.AuthorizeAsync("ORD-4", new Money(10m, "EUR"), CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Fact]
    public async Task An_unrecognized_status_value_is_read_back_as_declined()
    {
        server.RespondWith(HttpStatusCode.OK, """{"status":"pending_review"}""");

        var outcome = await sut.AuthorizeAsync("ORD-5", new Money(10m, "EUR"), CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Fact]
    public async Task An_unexpected_server_error_surfaces_as_a_failure_instead_of_a_silent_decline()
    {
        server.RespondWith(HttpStatusCode.InternalServerError, "");

        await Assert.ThrowsAsync<HttpRequestException>(
            () => sut.AuthorizeAsync("ORD-6", new Money(10m, "EUR"), CancellationToken.None));
    }

    /// <summary>A minimal, real HTTP server standing in for the payment provider's REST API.</summary>
    private sealed class FakeProviderServer : IDisposable
    {
        private readonly HttpListener listener = new();
        private HttpStatusCode nextStatus = HttpStatusCode.OK;
        private string nextBody = "";

        public string BaseAddress { get; } = $"http://127.0.0.1:{GetFreePort()}/";

        public CapturedRequest LastRequest { get; private set; } = null!;

        public void Start()
        {
            listener.Prefixes.Add(BaseAddress);
            listener.Start();
            _ = ListenLoopAsync();
        }

        public void RespondWith(HttpStatusCode status, string body)
        {
            nextStatus = status;
            nextBody = body;
        }

        private async Task ListenLoopAsync()
        {
            while (listener.IsListening)
            {
                HttpListenerContext context;
                try
                {
                    context = await listener.GetContextAsync();
                }
                catch (Exception) when (!listener.IsListening)
                {
                    return;
                }

                using var reader = new StreamReader(context.Request.InputStream, Encoding.UTF8);
                var body = await reader.ReadToEndAsync();
                LastRequest = new CapturedRequest(context.Request.HttpMethod, context.Request.Url!.AbsolutePath, body);

                context.Response.StatusCode = (int)nextStatus;
                var bytes = Encoding.UTF8.GetBytes(nextBody);
                context.Response.ContentType = "application/json";
                context.Response.ContentLength64 = bytes.Length;
                await context.Response.OutputStream.WriteAsync(bytes);
                context.Response.Close();
            }
        }

        private static int GetFreePort()
        {
            using var socket = new System.Net.Sockets.Socket(
                System.Net.Sockets.AddressFamily.InterNetwork,
                System.Net.Sockets.SocketType.Stream,
                System.Net.Sockets.ProtocolType.Tcp);
            socket.Bind(new IPEndPoint(IPAddress.Loopback, 0));
            return ((IPEndPoint)socket.LocalEndPoint!).Port;
        }

        public void Dispose()
        {
            listener.Stop();
            listener.Close();
        }
    }

    private sealed record CapturedRequest(string Method, string Path, string Body);
}

